function buildJoinQuery(config) {
  const parts = [];

  parts.push(`SELECT ${config.select.join(', ')}`);
  parts.push(`FROM ${config.from}`);

  if (config.joins) {
    for (const join of config.joins) {
      parts.push(`${join.type} JOIN ${join.table} ON ${join.on.left} = ${join.on.right}`);
    }
  }

  if (config.where && config.where.length) {
    const conditions = config.where.map(c => {
      let val = c.value;
      if (typeof val === 'string') val = `'${val}'`;
      else if (typeof val === 'boolean') val = val.toString();
      return `${c.column} ${c.operator} ${val}`;
    });
    parts.push(`WHERE ${conditions.join(' AND ')}`);
  }

  if (config.orderBy && config.orderBy.length) {
    const orders = config.orderBy.map(o => `${o.column} ${o.direction}`);
    parts.push(`ORDER BY ${orders.join(', ')}`);
  }

  if (config.limit !== undefined) {
    parts.push(`LIMIT ${config.limit}`);
  }

  return parts.join(' ');
}
